export interface RateLimiterOptions {
  max: number
  windowMs: number
  mode: 'fixed' | 'sliding'
}

export class RateLimiter {
  private readonly max: number
  private readonly counts = new Map<string, number>()

  constructor(options: RateLimiterOptions) {
    this.max = options.max
  }

